"""Fill background regions unreachable from top/bottom edges with 4."""
import json, os
from collections import deque, Counter

P = os.path.dirname(os.path.abspath(__file__))

def background(grid):
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def fill_enclosed(grid, fill, seed_edges=("top", "bottom")):
    h, w = len(grid), len(grid[0])
    bg = background(grid)
    seen = [[False] * w for _ in range(h)]
    q = deque()
    for j in range(w):
        for i in range(h):
            on = (i == 0 and "top" in seed_edges) or (i == h - 1 and "bottom" in seed_edges)
            if on and grid[i][j] == bg and not seen[i][j]:
                seen[i][j] = True
                q.append((i, j))
    while q:
        a, b = q.popleft()
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            x, y = a + di, b + dj
            if 0 <= x < h and 0 <= y < w and grid[x][y] == bg and not seen[x][y]:
                seen[x][y] = True
                q.append((x, y))
    return [[fill if grid[i][j] == bg and not seen[i][j] else grid[i][j]
             for j in range(w)] for i in range(h)]

def transform(grid):
    return fill_enclosed(grid, 4)
